#include <stdio.h>
#include <string.h>

int main() {
    int N, T;
    scanf("%d %d", &N, &T);

    int A[105], B[105];
    for (int i = 0; i < N; i++) {
        scanf("%d %d", &A[i], &B[i]);
    }

    int cap = T - 1;
    int ans = 0;

    // dp[j] = knapsack without dish j, capacity cap
    // For each j as last dish
    int dp[10005];

    for (int j = 0; j < N; j++) {
        // Knapsack over all dishes except j
        memset(dp, 0, sizeof(int) * (cap + 1));
        for (int i = 0; i < N; i++) {
            if (i == j) continue;
            // 0/1 knapsack, iterate backwards
            for (int w = cap; w >= A[i]; w--) {
                if (dp[w - A[i]] + B[i] > dp[w]) {
                    dp[w] = dp[w - A[i]] + B[i];
                }
            }
        }
        int best = dp[cap] + B[j];
        if (best > ans) ans = best;
    }

    printf("%d\n", ans);
    return 0;
}

#include <stdio.h>

#define MAX_N 3000
#define MAX_T 3000

int max(int a, int b) {
    return a > b ? a : b;
}

int main() {
    int N, T;
    scanf("%d %d", &N, &T);

    int A[MAX_N], B[MAX_N];
    for (int i = 0; i < N; i++) {
        scanf("%d %d", &A[i], &B[i]);
    }

    // DP array: dp[t] = max deliciousness using exactly t minutes
    int dp[MAX_T + 1] = {0};

    int ans = 0;

    for (int i = 0; i < N; i++) {
        // Try to use this dish as the last one
        // We can order it at any time so that we finish after T-0.5
        // So we consider all possible times before T where we can start it
        for (int t = 0; t < T; t++) {
            if (dp[t] > 0 || t == 0) {
                ans = max(ans, dp[t] + B[i]);
            }
        }

        // Now update dp with this dish as a non-last dish
        for (int t = T - 1; t >= A[i]; t--) {
            if (dp[t - A[i]] > 0 || t - A[i] == 0) {
                dp[t] = max(dp[t], dp[t - A[i]] + B[i]);
            }
        }
        // Also consider taking it as the only dish
        if (A[i] < T) {
            dp[A[i]] = max(dp[A[i]], B[i]);
        }
    }

    // Also consider the case where last dish is never needed beyond time limit
    for (int t = 0; t < T; t++) {
        ans = max(ans, dp[t]);
    }

    printf("%d\n", ans);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static int max(int a, int b) { return a > b ? a : b; }

typedef struct {
    int a, b;
} Dish;

int cmp_dish(const void *p, const void *q) {
    const Dish *x = (const Dish *)p;
    const Dish *y = (const Dish *)q;
    return x->a - y->a;
}

int main(void) {
    int N, T;
    if (scanf("%d %d", &N, &T) != 2) return 0;

    Dish *d = (Dish *)malloc(sizeof(Dish) * N);
    for (int i = 0; i < N; i++) {
        scanf("%d %d", &d[i].a, &d[i].b);
    }

    qsort(d, N, sizeof(Dish), cmp_dish);

    /* dp[t] = maximum deliciousness achievable with total eating time exactly/within t
       before ordering the last dish, where t < T */
    int *dp = (int *)calloc(T, sizeof(int));

    int ans = 0;

    for (int i = 0; i < N; i++) {
        int a = d[i].a, b = d[i].b;

        /* Consider this dish as the last ordered dish.
           Previous dishes must finish within time < T. */
        for (int t = 0; t < T; t++) {
            ans = max(ans, dp[t] + b);
        }

        /* Standard 0/1 knapsack transition for dishes eaten before the last one.
           Only states with total time < T are allowed. */
        for (int t = T - 1; t >= a; t--) {
            dp[t] = max(dp[t], dp[t - a] + b);
        }
    }

    printf("%d\n", ans);

    free(dp);
    free(d);
    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int T = sc.nextInt();

        int[][] dishes = new int[N][2];
        for (int i = 0; i < N; i++) {
            dishes[i][0] = sc.nextInt(); // A_i
            dishes[i][1] = sc.nextInt(); // B_i
        }

        // Sort by eating time
        Arrays.sort(dishes, (a, b) -> Integer.compare(a[0], b[0]));

        int maxTime = T;
        long[] dp = new long[maxTime];

        for (int i = 0; i < N; i++) {
            int time = dishes[i][0];
            int value = dishes[i][1];
            // We process in reverse to avoid using same dish twice
            for (int j = maxTime - 1; j >= time; j--) {
                dp[j] = Math.max(dp[j], dp[j - time] + value);
            }
        }

        // Now consider the last dish can be eaten after T - 0.5
        long result = 0;
        for (int i = 0; i < N; i++) {
            int time = dishes[i][0];
            int value = dishes[i][1];
            // If we order this one last, we have up to (T-1) time for others
            if (time <= T) {
                long bestPrev = 0;
                for (int j = 0; j < T; j++) {
                    bestPrev = Math.max(bestPrev, dp[j]);
                }
                // But careful: dp already includes all dishes, we need to exclude current from bestPrev
                // Instead: compute max from dp excluding current dish
                // Simpler approach: use dp from before adding this dish
            }
        }

        // More accurate method:
        long[] dpPrev = new long[maxTime];
        for (int i = 0; i < N; i++) {
            int time = dishes[i][0];
            int value = dishes[i][1];
            long[] newDp = dpPrev.clone();
            for (int j = time; j < maxTime; j++) {
                newDp[j] = Math.max(newDp[j], dpPrev[j - time] + value);
            }
            // Consider this dish as last
            long maxPrev = 0;
            for (int j = 0; j < maxTime; j++) {
                maxPrev = Math.max(maxPrev, dpPrev[j]);
            }
            result = Math.max(result, maxPrev + value);
            dpPrev = newDp;
        }

        System.out.println(result);
    }
}

