public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int T = Integer.parseInt(st.nextToken());

        int[] A = new int[N];
        int[] B = new int[N];
        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            A[i] = Integer.parseInt(st.nextToken());
            B[i] = Integer.parseInt(st.nextToken());
        }

        // Sort by A ascending
        Integer[] idx = new Integer[N];
        for (int i = 0; i < N; i++) idx[i] = i;
        Arrays.sort(idx, (x, y) -> A[x] - A[y]);

        int capacity = T - 1;
        // dp[w] = max deliciousness using dishes added so far with total A = w
        long[] dp = new long[capacity + 1];
        Arrays.fill(dp, Long.MIN_VALUE / 2);
        dp[0] = 0;

        long ans = 0;

        for (int k = 0; k < N; k++) {
            int j = idx[k];
            // Best subset from dishes 0..k-1 (all have A <= A[j]) with sum <= T-1, plus dish j
            // Find max dp[w] for w in [0, capacity]
            long best = Long.MIN_VALUE / 2;
            for (int w = 0; w <= capacity; w++) {
                if (dp[w] > best) best = dp[w];
            }
            if (best > Long.MIN_VALUE / 2) {
                ans = Math.max(ans, best + B[j]);
            }
            // Also just dish j alone
            ans = Math.max(ans, B[j]);

            // Add dish j to knapsack
            for (int w = capacity; w >= A[j]; w--) {
                if (dp[w - A[j]] > Long.MIN_VALUE / 2) {
                    dp[w] = Math.max(dp[w], dp[w - A[j]] + B[j]);
                }
            }
        }

        System.out.println(ans);
    }
}

