public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int T = fs.nextInt();

        int[] A = new int[N];
        int[] B = new int[N];
        for (int i = 0; i < N; i++) {
            A[i] = fs.nextInt();
            B[i] = fs.nextInt();
        }

        // Sort by eating time
        Integer[] ord = new Integer[N];
        for (int i = 0; i < N; i++) ord[i] = i;
        Arrays.sort(ord, Comparator.comparingInt(i -> A[i]));

        long[][] dp = new long[N + 1][T];
        for (int i = 0; i <= N; i++) Arrays.fill(dp[i], -1);
        dp[0][0] = 0;

        long ans = 0;

        for (int i = 0; i < N; i++) {
            int idx = ord[i];
            int a = A[idx];
            int b = B[idx];

            for (int t = 0; t < T; t++) {
                if (dp[i][t] < 0) continue;

                // Do not take this dish before the last order
                dp[i + 1][t] = Math.max(dp[i + 1][t], dp[i][t]);

                // Take this dish as a normal dish if it finishes before T
                if (t + a < T) {
                    dp[i + 1][t + a] = Math.max(dp[i + 1][t + a], dp[i][t] + b);
                }

                // Take this dish as the last ordered dish
                ans = Math.max(ans, dp[i][t] + b);
            }
        }

        System.out.println(ans);
    }
}

