int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, T;
    cin >> N >> T;
    vector<pair<int,int>> dishes(N);
    for (int i = 0; i < N; i++) {
        cin >> dishes[i].first >> dishes[i].second;
    }

    // Sort by eating time
    sort(dishes.begin(), dishes.end());

    vector<long long> dp(T, 0); // dp[t] = max happiness using exactly t minutes
    long long ans = 0;

    for (auto &[a, b] : dishes) {
        // Consider this dish as the last one
        for (int t = T - 1; t >= 0; t--) {
            if (t + a <= T - 1) {
                // Not last: normal knapsack update
                dp[t + a] = max(dp[t + a], dp[t] + b);
            }
            // As last dish: start at time t (t <= T-1), finish after T
            if (t + a >= T) {
                ans = max(ans, dp[t] + b);
            }
        }
    }

    // Also consider case where we never take a "last dish" extending beyond T
    for (int t = 0; t < T; t++) {
        ans = max(ans, dp[t]);
    }

    cout << ans << "\n";
    return 0;
}

