    vector<int> A(N), B(N);
    for(int i=0;i<N;i++) cin>>A[i]>>B[i];
    // dp[j] = max happiness with total time <= j, using subset of all items
    // For last item trick: answer = max over j of (dp_without_j[T-1] + B[j])
    // Also consider dp[T-1] (no "extension" needed if all fit)
    vector<int> dp(T, 0);
    for(int i=0;i<N;i++)
        for(int t=T-1;t>=A[i];t--)
            dp[t]=max(dp[t], dp[t-A[i]]+B[i]);
    int ans = dp[T-1];
    // Try each as last item
    for(int j=0;j<N;j++){
        // recompute knapsack without item j
        vector<int> dp2(T,0);
        for(int i=0;i<N;i++){
            if(i==j) continue;
            for(int t=T-1;t>=A[i];t--)
                dp2[t]=max(dp2[t],dp2[t-A[i]]+B[i]);
        }
        ans=max(ans, dp2[T-1]+B[j]);
    }
    cout<<ans<<endl;
}

