    vector<long long> dp(T, 0);

    long long ans = 0;

    for (int i = 0; i < N; i++) {
        int a = dishes[i].first;
        int b = dishes[i].second;

        // Consider this dish as the last ordered one.
        for (int t = 0; t < T; t++) {
            ans = max(ans, dp[t] + b);
        }

        // Normal 0/1 knapsack transition for dishes eaten before time T.
        for (int t = T - 1; t >= a; t--) {
            dp[t] = max(dp[t], dp[t - a] + b);
        }
    }

    cout << ans << '\n';
    return 0;
